Lemma handoff_view : ltac2:(tb__ "0|8|
S8S8SdS18S35A1M0S30S34S6S0ScS20R8R6S19G0S32R5S33R4R3A2A4A4S21Q40M1A1S36RaS9R8A1M2R1A3S1S16S21Q8M3A1M4A1M5S7RaR2A2S31R7R2A2A3F_;Fa;S5S1S24S25G2R4R3A3S27A3A1S2aS23G1SaRbR5A2A2R4A2S0S2S2S2bZ0R1A2S2dR1S2cZ2Z40A2A2A2S2S3G4G4S1G5S37S20S7RcA1R2A3M6S17G4R1A2M7A3Lb;A2S24OLx;S25S9RaA1R6R5A3S4S4S0S1G5G6S17G4S22G3R1A2A2A3Lb;S2S1G5S7RbS22G1R1A2A2S1dG4A1A3S3G4G4S1G5S14S20S22G1R2A2A2G7A3Lb;A2A2X24x4A2A2Tz;F_;F_;F_;Foff;Fbase;Fmd;Fms;Ftr;FS;FrhoM;Frho1;").
Proof.
  intros rho1 rhoM S tr ms md base off Hsm Hrm Hbi z.
  pose proof (proj1 (smatch_mm segsA _ _ _ _ _ Hsm)) as HOL. pose proof Hsm as (_ & _ & _ & _ & ROM & _). cbn [fst snd cfg_ms cfg_model] in ROM.
  destruct (find_cov (ss_objs S) base off) as [o|] eqn:Hf.
  2:{ exfalso. apply Hbi. unfold byte_info. rewrite Hf. reflexivity. }
  destruct (find_cov_spec _ _ _ _ Hf) as (Hin & Hbase & lo & hi & Hlo & Hhi & Hoff & _).
  pose proof (byte_info_sound segsA rho1 ms (ss_objs S) HOL ROM base off o Hf) as X. cbv zeta in X.
  destruct X as (Ho & HB & Hz & _ & [b Hrd] & Hm).
  assert (IN : in_ranges rho1 (ss_objs S) (Z_to_bv 64 z)).
  { exists o. split; [exact Hin|]. unfold obj_range, obj_lo_of, obj_hi_of. rewrite Hbase. cbn [fst snd].
    rewrite (soff_small rho1 _ _ Hlo), (soff_small rho1 _ _ Hhi). subst z. rewrite u64_lit by lia. lia. }
  assert (RD : view segsA (rm rhoM) z = rd ms (Z_to_bv 64 z)).
  { rewrite view_in by (subst z; lia). unfold rd_of, rd, ms_read_byte. rewrite (Hrm _ IN). fold z.
    destruct (ms_mem ms (Z_to_bv 64 z)); [reflexivity|]. symmetry. apply ROM. }
  split; [subst z; exact Hz|]. split; [exists b; rewrite RD; exact Hrd|].
  destruct (byte_info (ss_objs S) base off); try exact I.
  - rewrite RD. exact Hm.
  - destruct Hm as [Hn Hi]. split; [| exact Hi]. rewrite (Hrm _ IN). exact Hn.
Qed.

Lemma handoff_view_zero_range : ltac2:(tb__ "0|6|
S8S8SdS18S35A1M0S30S34S6S18S0A1ScS20R8R6S19G0S32R5S33R4R3A2A4A4S21Q40M1A1S36RaS9R8A1R1A3S1S16S21Q8M2A1M3A1M4S7RaR2A2S31R7R2A2A3F_;Fa;S1S1aS39S0S0S26S25S9R9A1R5R1A3S28Z0M5A1A2Loff;R3A3S1cA3S0S38S0R1R5A3S1G4S37S20S7RcA1S2aS23G1SaRdR7A2A2R2A2A3S17G3S22G2G5A2A2A3F_;Foff;F_;F_;F_;Foffs;Fbase;Fmd;Fms;Ftr;FS;FrhoM;Frho1;").
Proof.
  intros rho1 rhoM S tr ms md base offs Hsm Hrm Hall off Hin.
  pose proof (proj1 (forallb_forall _ _) Hall off Hin) as E. cbn beta in E. apply binfo_eqb_sound in E.
  pose proof (handoff_view rho1 rhoM S tr ms md base off Hsm Hrm ltac:(rewrite E; discriminate)) as (_ & _ & X). rewrite E in X. exact X.
Qed.

Lemma handoff_view_present_range : ltac2:(tb__ "0|4|
S8S8SdS18S35A1M0S30S34S6S18S0A1ScS20R8R6S19G0S32R5S33R4R3A2A4A4S21Q40M1A1S36RaS9R8A1R1A3S1S16S21Q8A1M2A1M3S7RaR2A2S31R7R2A2A3F_;Fa;S1S1aS39S0S0S1fS26S25S9R9A1R5R1A3S27A2A1Loff;R3A3S1cA3S0S38S0R1R5A3S3G2G2S1G3S37S20S7RdA1S2aS23G1SaReR8A2A2R3A2A3S17G2R1A2A3Lb;A2F_;Foff;F_;F_;F_;Foffs;Fbase;Fmd;Fms;Ftr;FS;FrhoM;Frho1;").
Proof.
  intros rho1 rhoM S tr ms md base offs Hsm Hrm Hall off Hin.
  pose proof (proj1 (forallb_forall _ _) Hall off Hin) as E. cbn beta in E. apply Bool.negb_true_iff in E.
  assert (NE : byte_info (ss_objs S) base off <> BNone) by (intros X; rewrite X in E; discriminate).
  exact (proj1 (proj2 (handoff_view rho1 rhoM S tr ms md base off Hsm Hrm NE))).
Qed.

Fixpoint find_cellv (cells : list cell) (off : Z) : option (Z * sv) :=
  match cells with
  | [] => None
  | c :: r => match c_off c with
              | SLit o => if o =? off then Some (c_width c, SymState.c_val c) else find_cellv r off
              | _ => find_cellv r off
              end
  end.
Definition cell_info (L : list sobj) (base : sv) (off : Z) : option (Z * sv) := ltac2:(tb__ "0|1|
S16SeA1S16S1bS0S6A2M0A1Lx;S29VL;Vbase;Voff;A3SeS3aS15R1A1Voff;A2Lo;S1dG0A1X16x2").

Lemma find_cellv_spec : ltac2:(tb__ "0|1|
S18SbA1S0S0S6S1S16S1bS0S6A2M0A1S3aR4R3A2S17G0S19S0S6R2R1A4A2A3S3SbSbS2S38SbR1R6A3S2S1S6S10R1A1SfR5A1A3S2S1S0S12R1A1R4A3S1S6S11R1A1R3A3A2A2A2Lc;A2F_;Fv;Fw;Foff;Fcells;").
Proof.
  induction cells as [|c r IH]; intros off w v H; cbn [find_cellv] in H; [discriminate|].
  destruct (c_off c) as [o| | | | | | |] eqn:Eo; try (destruct (IH off w v H) as (c' & Hin & X); exists c'; split; [right; exact Hin | exact X]).
  destruct (Z.eqb_spec o off) as [->|NE].
  - injection H as <- <-. exists c. split; [left; reflexivity|]. split; [exact Eo|]. split; reflexivity.
  - destruct (IH off w v H) as (c' & Hin & X). exists c'. split; [right; exact Hin | exact X].
Qed.

Lemma handoff_cell : ltac2:(tb__ "0|8|
S8S8SdS18S35A1M0S30S34S6S0S0S6ScS20RaR8S19G0S32R7S33R6R5A2A4A4S21Q40M1A1S36RcS9RaA1M2R1A3S1S16S21Q8M3A1M4A1M5S7RcR2A2S31R9R2A2A3F_;Fa;S1S16S1bS0S6A2M6A1S3bG2R6R5A3S17G6S19S0S6R4R3A4A2A3S2aS23G1SaRdR7A2A2R6A2S0S2S2bZ0M7R1A2S2S2bS2aR1R6A2S2cZ2Z40A2A2S1eS3cR1S2eR7A1A2S1G5S37S20S7RfA1S2aR3S2fR2A1A2A3S17G4S3dG4R2S13S2eR8A1SaR10R7A2A2S22G3G7A2A4A2A3F_;Fj;A2A2Tz;F_;F_;F_;Fv;Fw;Foff;Fbase;Fmd;Fms;Ftr;FS;FrhoM;Frho1;").
Proof.
  intros rho1 rhoM S tr ms md base off w v Hsm Hrm Hci z.
  pose proof (proj1 (smatch_mm segsA _ _ _ _ _ Hsm)) as HOL. pose proof Hsm as (_ & _ & _ & _ & ROM & _). cbn [fst snd cfg_ms cfg_model] in ROM.
  unfold cell_info in Hci. destruct (find_cov (ss_objs S) base off) as [o|] eqn:Hf; [|discriminate].
  destruct (find_cov_spec _ _ _ _ Hf) as (Hin & Hbase & lo & hi & Hlo & Hhi & Hoff & _).
  destruct (find_cellv_spec _ _ _ _ Hci) as (c & Hc & Co & Cw & Cv).
  pose proof (proj1 (Forall_forall _ _) HOL o Hin) as Ho. pose proof Ho as (Hb & _ & HC & _).
  pose proof (lit_small_Some _ _ Hlo) as [_ Blo]. pose proof (lit_small_Some _ _ Hhi) as [_ Bhi].
  pose proof (proj1 (Forall_forall _ _) HC c Hc) as (C1 & C2 & C3). rewrite Co in C1, C2, C3. rewrite Cw in C2, C3. rewrite Cv, Hbase in C3.
  rewrite soff_lit_small in C1, C2, C3 by lia.
  unfold obj_lo_of, obj_hi_of in Hb, C1, C2. rewrite (soff_small rho1 _ _ Hlo) in Hb, C1. rewrite (soff_small rho1 _ _ Hhi) in Hb, C2. rewrite Hbase in Hb.
  destruct Hb as (B1 & B2 & B3 & B4).
  assert (UO : bv_unsigned (oaddr rho1 base off) = z).
  { unfold oaddr. subst z. rewrite u64_lit by lia. reflexivity. }
  split; [subst z; lia|]. split; [subst z; lia|].
  intros j Hj.
  assert (IN : in_ranges rho1 (ss_objs S) (Z_to_bv 64 (z + Z.of_nat j))).
  { exists o. split; [exact Hin|]. unfold obj_range, obj_lo_of, obj_hi_of. rewrite Hbase. cbn [fst snd].
    rewrite (soff_small rho1 _ _ Hlo), (soff_small rho1 _ _ Hhi). rewrite u64_lit by (subst z; lia). subst z. lia. }
  pose proof (rd_bytes_nth ms (Z.to_nat w) (oaddr rho1 base off) _ j C3 Hj ltac:(rewrite UO; subst z; lia)) as R. rewrite UO in R.
  rewrite view_in by (subst z; lia). unfold rd_of. unfold rd, ms_read_byte in R. rewrite (Hrm _ IN).
  destruct (ms_mem ms (Z_to_bv 64 (z + Z.of_nat j))); [exact R|]. rewrite <- R. symmetry. apply ROM.
Qed.
